'use client';
import { useState, useEffect } from 'react';
import { User, Search, Shield, ShieldOff, Eye } from 'lucide-react';

export default function UserManagement() {
  const [users, setUsers] = useState([
     { id: 1, name: 'Rahul Sharma', phone: '9876543210', location: 'Andheri West, Mumbai', bookings: 5, status: 'Active', joined: '2023-01-15' },
     { id: 2, name: 'Priya Patel', phone: '9988776655', location: 'Bandra, Mumbai', bookings: 12, status: 'Active', joined: '2023-02-20' },
     { id: 3, name: 'Amit Kumar', phone: '9123456789', location: 'Dadar, Mumbai', bookings: 2, status: 'Blocked', joined: '2023-03-10' },
  ]);
  // Note: Actual user fetching would require a new API endpoint like /api/users
  
  const [searchTerm, setSearchTerm] = useState('');

  const toggleBlock = (id) => {
      setUsers(prev => prev.map(u => u.id === id ? { ...u, status: u.status === 'Active' ? 'Blocked' : 'Active' } : u));
  };

  const filteredUsers = users.filter(u => 
     u.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
     u.phone.includes(searchTerm)
  );

  return (
    <div>
        <h1 style={{ marginBottom: '2rem' }}>User Management</h1>

        {/* Search */}
        <div className="glass" style={{ padding: '1rem', display: 'flex', gap: '1rem', marginBottom: '2rem', alignItems: 'center' }}>
            <Search size={20} style={{ color: 'var(--text-muted)' }} />
            <input 
                type="text" 
                placeholder="Search users by name or phone..." 
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                style={{ background: 'transparent', border: 'none', color: '#fff', flex: 1, outline: 'none' }} 
            />
        </div>

        {/* Table */}
        <div className="glass" style={{ padding: '0', overflow: 'hidden' }}>
            <div style={{ overflowX: 'auto' }}>
                <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
                    <thead>
                        <tr style={{ borderBottom: '1px solid rgba(255,255,255,0.1)', background: 'rgba(255,255,255,0.02)' }}>
                            <th style={{ padding: '1rem' }}>User</th>
                            <th style={{ padding: '1rem' }}>Phone</th>
                            <th style={{ padding: '1rem' }}>Location</th>
                            <th style={{ padding: '1rem' }}>Total Bookings</th>
                            <th style={{ padding: '1rem' }}>Joined</th>
                            <th style={{ padding: '1rem' }}>Status</th>
                            <th style={{ padding: '1rem' }}>Actions</th>
                        </tr>
                    </thead>
                    <tbody>
                        {filteredUsers.map((user) => (
                            <tr key={user.id} style={{ borderBottom: '1px solid rgba(255,255,255,0.05)' }}>
                                <td style={{ padding: '1rem' }}>
                                    <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                                        <div style={{ width: '30px', height: '30px', borderRadius: '50%', background: 'rgba(255,255,255,0.1)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                                            <User size={16} />
                                        </div>
                                        {user.name}
                                    </div>
                                </td>
                                <td style={{ padding: '1rem' }}>{user.phone}</td>
                                <td style={{ padding: '1rem', color: 'var(--text-muted)' }}>{user.location}</td>
                                <td style={{ padding: '1rem', textAlign: 'center' }}>{user.bookings}</td>
                                <td style={{ padding: '1rem', fontSize: '0.9rem', color: 'var(--text-muted)' }}>{new Date(user.joined).toLocaleDateString()}</td>
                                <td style={{ padding: '1rem' }}>
                                    <span style={{ 
                                        padding: '4px 10px', 
                                        borderRadius: '20px', 
                                        fontSize: '0.8rem',
                                        background: user.status === 'Active' ? 'rgba(46, 204, 113, 0.2)' : 'rgba(231, 76, 60, 0.2)',
                                        color: user.status === 'Active' ? '#2ecc71' : '#e74c3c'
                                    }}>
                                        {user.status}
                                    </span>
                                </td>
                                <td style={{ padding: '1rem' }}>
                                    <div style={{ display: 'flex', gap: '0.5rem' }}>
                                        <button title="View History" style={{ background: 'rgba(255,255,255,0.05)', border: 'none', cursor: 'pointer', color: '#fff', padding: '6px', borderRadius: '4px' }}><Eye size={16} /></button>
                                        <button 
                                            onClick={() => toggleBlock(user.id)}
                                            title={user.status === 'Active' ? 'Block User' : 'Unblock User'} 
                                            style={{ 
                                                background: user.status === 'Active' ? 'rgba(231, 76, 60, 0.1)' : 'rgba(46, 204, 113, 0.1)', 
                                                border: 'none', 
                                                cursor: 'pointer', 
                                                color: user.status === 'Active' ? '#e74c3c' : '#2ecc71', 
                                                padding: '6px', 
                                                borderRadius: '4px' 
                                            }}
                                        >
                                            {user.status === 'Active' ? <ShieldOff size={16} /> : <Shield size={16} />}
                                        </button>
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
                {filteredUsers.length === 0 && (
                    <div style={{ padding: '3rem', textAlign: 'center', color: 'var(--text-muted)' }}>No users found.</div>
                )}
            </div>
        </div>
    </div>
  );
}
